-- Reviewed offline legal corpus: 60 distinct court/statute/article records.
INSERT INTO courts(court_id,name,level,region) VALUES ('court_shanghai_rules','Shanghai Public Legal Information Index','Intermediate court','Shanghai');

INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES
 ('legal_rule_temp_id_rail','Railway Passenger Temporary Travel Identity Certificate Rules','temporary identity certificate','Railway Station Police and official railway service channels','2026-01-01','currently effective','A passenger who loses an identity document must complete personal verification at a station police certificate desk or through an official railway channel before receiving a temporary identity certificate.'),
 ('legal_rule_reissue_remote','Resident Identity Document Remote Reissue and Verification Rules','remote identity document reissue','Shanghai Public Security Government Service Guide','2026-01-01','currently effective','Temporary identity certificate replacement verification is a personal, in-person process: the applicant must attend the service window, and the current official material list controls.'),
 ('legal_rule_email_invalid','Sensitive Document Submission and Ordinary Email Warning','ordinary email is invalid','Shanghai Government Data Security Guidance','2026-01-01','currently effective','Ordinary email sensitive documents are not an accepted submission route: identity documents, household-registration pages, death certificates, and bank statements must stay within an official channel.');

INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES
 ('art_temp_id_001','legal_rule_temp_id_rail','Article 1',1,'Personal verification at the station','When an identity document is lost, the passenger must present verifiable information in person at the station police certificate desk or use an official railway channel to obtain a temporary travel identity certificate.'),
 ('art_temp_id_002','legal_rule_temp_id_rail','Article 2',2,'Allow time for identity checks','A temporary identity certificate requires human verification. The passenger should arrive early enough for the station police or official channel to complete that check before boarding.'),
 ('art_reissue_001','legal_rule_reissue_remote','Article 1',1,'In-person attendance required','Remote reissue of a resident identity document requires the applicant to attend in person for identity capture or verification; another person may not substitute for the applicant.'),
 ('art_reissue_002','legal_rule_reissue_remote','Article 2',2,'Official material verification','Household-registration pages, death certificates, and relationship explanations must follow the service window or official system requirements; a summary is not a promise of approval.'),
 ('art_email_001','legal_rule_email_invalid','Article 1',1,'Ordinary email is not a secure route','Ordinary email is not a safe or accepted route for identity-document photos, household-registration pages, death certificates, or bank statements. Do not send sensitive documents for informal precheck.');

WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<17)
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary)
SELECT printf('legal_reference_%02d',n),
       CASE n WHEN 1 THEN 'Railway Refund and Change Rules' WHEN 2 THEN 'Elder Passenger E-Ticket Service Guide' WHEN 3 THEN 'Involuntary Airline Change Procedure' WHEN 4 THEN 'Hotel Real-Name Registration Notice' WHEN 5 THEN 'Minimum Necessary Personal Information Guide' WHEN 6 THEN 'Government Appointment Change Rules' WHEN 7 THEN 'Bank Transfer Authorization Notice' WHEN 8 THEN 'Funeral Service Fee Disclosure' WHEN 9 THEN 'Road Construction Information Standard' WHEN 10 THEN 'Accessible Public Transit Service Guide' WHEN 11 THEN 'Railway Waitlist Order Handling Rules' WHEN 12 THEN 'Consumer Prepayment Warning' WHEN 13 THEN 'Email Anti-Phishing Guide' WHEN 14 THEN 'Remote Medical Material Verification' WHEN 15 THEN 'Hotel Cancellation Disclosure Rules' WHEN 16 THEN 'Emergency Contact Privacy Rules' ELSE 'Public Service Complaint Procedure' END,
       CASE n WHEN 1 THEN 'rail refund' WHEN 2 THEN 'elder ticket' WHEN 3 THEN 'flight change' WHEN 4 THEN 'hotel registration' WHEN 5 THEN 'minimum necessary' WHEN 6 THEN 'appointment change' WHEN 7 THEN 'payment authorization' WHEN 8 THEN 'funeral fees' WHEN 9 THEN 'road construction' WHEN 10 THEN 'accessibility' WHEN 11 THEN 'waitlist handling' WHEN 12 THEN 'prepayment' WHEN 13 THEN 'anti-phishing' WHEN 14 THEN 'medical materials' WHEN 15 THEN 'cancellation terms' WHEN 16 THEN 'contact privacy' ELSE 'complaint procedure' END,
       CASE n%4 WHEN 0 THEN 'Transportation public information service' WHEN 1 THEN 'Shanghai government service materials' WHEN 2 THEN 'Consumer rights protection materials' ELSE 'Public safety service materials' END,
       '2025-01-01','currently effective',
       CASE n WHEN 1 THEN 'Refund and change fees depend on ticket type, time before departure, and the carrier conditions.' WHEN 2 THEN 'The station can provide human guidance, but the passenger must still carry verifiable identity information.' WHEN 3 THEN 'For an involuntary change, retain the original order and carrier notice as evidence.' WHEN 4 THEN 'Hotel registration must verify the guest; a platform order cannot replace on-site registration.' WHEN 5 THEN 'Personal data processing must be limited by purpose, fields, and retention period.' WHEN 6 THEN 'After a system appointment change, use the newest confirmation and recheck the place.' WHEN 7 THEN 'A large transfer requires checking the recipient, amount, purpose, and explicit user authorization.' WHEN 8 THEN 'Funeral service items, amounts, and payee must be clear and receipts retained.' WHEN 9 THEN 'Construction information should state the active period, impact area, and practical detour.' WHEN 10 THEN 'Services for elder passengers should give clear directions and reduce complex transfers.' WHEN 11 THEN 'Waitlist outcome, refund status, and replacement train must be checked separately.' WHEN 12 THEN 'Before prepayment, identify refund conditions, responsible provider, and dispute channel.' WHEN 13 THEN 'For an unfamiliar email requesting sensitive identity documents, verify the domain and official contact first.' WHEN 14 THEN 'Remote medical materials and identity reissue materials have different scopes and cannot replace one another.' WHEN 15 THEN 'A lodging product must show its cancellation deadline, fee, and non-refundable condition before payment.' WHEN 16 THEN 'Emergency contact information is for necessary communication only, not marketing or public records.' ELSE 'A public-service complaint should retain its time, channel, subject, and handling number.' END
FROM seq;

WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<34)
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text)
SELECT printf('art_reference_%03d',n),printf('legal_reference_%02d',((n-1)%17)+1),printf('Article %d',1+((n-1)/17)),1+((n-1)/17),
       CASE ((n-1)%17)+1 WHEN 1 THEN 'Time and ticket type' WHEN 2 THEN 'Human assistance' WHEN 3 THEN 'Change evidence' WHEN 4 THEN 'On-site verification' WHEN 5 THEN 'Field control' WHEN 6 THEN 'Latest record' WHEN 7 THEN 'Four-point authorization check' WHEN 8 THEN 'Fee traceability' WHEN 9 THEN 'Impact area' WHEN 10 THEN 'Elder convenience' WHEN 11 THEN 'Status distinction' WHEN 12 THEN 'Refund conditions' WHEN 13 THEN 'Sender verification' WHEN 14 THEN 'Scope boundary' WHEN 15 THEN 'Cancellation disclosure' WHEN 16 THEN 'Limited purpose' ELSE 'Handling number' END,
       CASE ((n-1)%17)+1 WHEN 1 THEN 'Before changing a ticket, confirm the product rule and time before departure; do not rely on one universal rate.' WHEN 2 THEN 'An elder passenger may request human assistance and should also carry a printed or large-print itinerary.' WHEN 3 THEN 'When a flight changes, preserve the status notice and confirm authorization before accepting an alternative.' WHEN 4 THEN 'A platform confirmation proves a reservation only; actual stay remains subject to real-name registration.' WHEN 5 THEN 'Collect only identity fields needed for the current service and delete copies on the agreed schedule.' WHEN 6 THEN 'After an appointment changes, update reminders, route, and external notice instead of reusing the old number.' WHEN 7 THEN 'Before payment, check the account, amount, purpose, and whether the user clearly agreed.' WHEN 8 THEN 'A service charge should have a checkable item list, with receipts retained for cash or transfer.' WHEN 9 THEN 'A road event should state start, end, impact, and an alternate route suitable for pedestrians.' WHEN 10 THEN 'When an elder travels alone, reduce transfer complexity and clearly provide the train and meeting exit.' WHEN 11 THEN 'A failed waitlist does not mean a refund has arrived; check order and funds separately.' WHEN 12 THEN 'A prepaid item must disclose the provider, refund condition, and dispute process before payment.' WHEN 13 THEN 'Stop sending when an unfamiliar domain requests identity documents and verify independently through an official channel.' WHEN 14 THEN 'A guide from an adjacent field is only a reference and cannot replace the formal requirement for this matter.' WHEN 15 THEN 'Hotel cancellation terms must state the deadline, time zone, and actual fee after the deadline.' WHEN 16 THEN 'A contact phone and relationship may be used for an emergency only and must not be copied into a public ledger.' ELSE 'After filing a complaint, record the time, channel, handling number, and next follow-up point.' END
FROM seq;
